mapper.select:
SELECT t.bus_no AS id, t.bus_no AS busNo, t.status_enum AS statusEnum, o.name AS warehouseName, IFNULL(SUM(t.profit_loss_price), 0) AS profitLossPrice, app.name AS applicantName, t.apply_time AS applyTime, appr.name AS approverName, t.approval_time AS approvalTime FROM wkf_supply_request t LEFT JOIN adm_organization o ON o.id = t.purpose_location_id AND o.is_deleted = 0 LEFT JOIN adm_practitioner app ON app.id = t.applicant_id AND app.is_deleted = 0 LEFT JOIN adm_practitioner appr ON appr.id = t.approver_id AND appr.is_deleted = 0 WHERE t.is_deleted = 0 AND t.type_enum = 'INVENTORY_CHECK'
AND t.bus_no LIKE CONCAT('%', #{busNo}, '%')
AND t.status_enum = #{statusEnum}
AND t.purpose_location_id = #{warehouseId}
AND t.applicant_id = #{applicantId}
AND t.created_at >= #{startTime}
AND t.created_at <= #{endTime}
GROUP BY t.bus_no, t.status_enum, o.name, app.name, appr.name, t.apply_time, t.approval_time ORDER BY t.apply_time DESC, t.bus_no DESC
